            " please rename."
        )
        raise ValueError(
            create_message(message=msg, error_code=ErrorCode.INVALID_PROMPT_INPUT)
        )
    if "stop" in self.partial_variables:
        msg = (
            "Cannot have an partial variable named 'stop', as it is used "
