        )
        raise ValueError(
            create_message(message=msg, error_code=ErrorCode.INVALID_PROMPT_INPUT)
        )

    overall = set(self.input_variables).intersection(self.partial_variables)
    if overall:
        msg = f"Found overlapping input and partial variables: {overall}"
